"""Figures for the week 9 "Financial Costs" and "Misdirected Research" slides.

Writes straight into docs/assets/llms/. Sources go in the slide captions, not
the images. Numbers are copied from Strubell, Ganesh & McCallum (ACL 2019),
Table 4; see docs/assets/llms/SOURCES.md.

    python3 sandbox/llm-visual-options/make_options.py
"""
from pathlib import Path

import matplotlib

matplotlib.use("svg")
import matplotlib.pyplot as plt
from matplotlib import font_manager

ROOT = Path(__file__).resolve().parents[2]
OUT = ROOT / "docs" / "assets" / "llms"

# Deck palette (docs/slides/theme/blue-line.scss).
INK, CHARCOAL, MUTED, QUIET, BORDER, SOFT = "#231f20", "#333333", "#666666", "#aaaaaa", "#d8d8d8", "#f4f4f4"
RED = "#c60c30"

font_manager.fontManager.addfont(str(ROOT / "docs/assets/fonts/mulish/Mulish-wght.ttf"))
plt.rcParams.update({
    "font.family": ["Mulish", "DejaVu Sans"],  # DejaVu only for glyphs Mulish lacks
    "font.size": 15,
    "text.color": INK,
    "text.parse_math": False,  # keep "$" literal
    "svg.fonttype": "path",
})

GOLDEN = (1 + 5 ** 0.5) / 2


def save(fig, name):
    fig.savefig(OUT / f"{name}.svg", bbox_inches="tight", transparent=True)
    plt.close(fig)


def rnd_cost():
    """Strubell et al. (2019), Table 4, on a linear axis: the full R&D bill dwarfs the model."""
    rows = [  # (label, detail, low, high)
        ("A single model", "1 model · 120 GPU-hours", 52, 175),
        ("Tuning for a new dataset", "24 models · 2,880 hours", 1238, 4205),
        ("All R&D for one paper", "4,789 models · 239,942 hours", 103000, 350000),
    ]
    fig, ax = plt.subplots(figsize=(10, 5.6))
    xs = range(len(rows))
    ax.bar(xs, [r[3] for r in rows], color=["#f3c3cd", "#e58397", RED], width=0.6)
    for x, (label, detail, lo, hi) in zip(xs, rows):
        ax.text(x, hi + 7000, f"${lo:,}–${hi:,}", ha="center", va="bottom", fontsize=15, fontweight="bold")
        ax.text(x, -0.05, label, ha="center", va="top", fontsize=15, fontweight="bold", transform=ax.get_xaxis_transform())
        ax.text(x, -0.13, detail, ha="center", va="top", fontsize=12, color=MUTED, transform=ax.get_xaxis_transform())
    ax.set_ylim(0, 400000)
    ax.set_yticks([0, 100000, 200000, 300000, 400000], ["$0", "$100k", "$200k", "$300k", "$400k"])
    ax.tick_params(axis="y", length=0, colors=MUTED)
    ax.set_xticks([])
    ax.grid(axis="y", color=BORDER, lw=0.8)
    ax.set_axisbelow(True)
    for side in ("top", "right", "left"):
        ax.spines[side].set_visible(False)
    ax.spines["bottom"].set_color(BORDER)
    ax.set_title("Cloud cost to develop one NLP model", loc="left", fontsize=18, fontweight="bold", pad=14)
    save(fig, "strubell-rnd-cost")


def two_approaches():
    """Structured knowledge above next-word statistics, in a golden-ratio portrait box."""
    width = 6
    fig, (top, bottom) = plt.subplots(2, 1, figsize=(width, width * GOLDEN))
    fig.subplots_adjust(left=0.08, right=0.92, top=0.92, bottom=0.02, hspace=0.3)
    for ax in (top, bottom):
        ax.set_xlim(0, 10)
        ax.set_ylim(0, 7.6)
        ax.axis("off")

    def node(ax, xy, text):
        return ax.text(*xy, text, ha="center", va="center", fontsize=21, fontweight="bold", color=INK, zorder=3,
                       bbox=dict(boxstyle="round,pad=0.45", fc=SOFT, ec=MUTED, lw=1.6))

    def edge_point(ax, box, toward, gap=0.18):
        """Where the line from a box's center toward a point leaves the box (data units), plus a gap."""
        fig.canvas.draw()  # boxes only have a size once rendered
        ext = box.get_bbox_patch().get_window_extent().transformed(ax.transData.inverted())
        (cx, cy), (tx, ty) = box.get_position(), toward
        dx, dy = tx - cx, ty - cy
        t = min(ext.width / 2 / abs(dx) if dx else float("inf"), ext.height / 2 / abs(dy) if dy else float("inf"))
        length = (dx**2 + dy**2) ** 0.5
        return cx + dx * t + gap * dx / length, cy + dy * t + gap * dy / length

    def arrow(ax, a, b, label=None, side=1, nudge=0):
        """Arrow that starts and ends just outside both boxes; label set beside its midpoint, off the line.

        `nudge` shifts a side label up or down (data units) so two labels on parallel edges don't share a baseline.
        """
        start = edge_point(ax, a, b.get_position())
        end = edge_point(ax, b, a.get_position())
        ax.annotate("", xy=end, xytext=start, zorder=2,
                    arrowprops=dict(arrowstyle="-|>,head_length=0.6,head_width=0.3", mutation_scale=22, color=CHARCOAL, lw=2,
                                    shrinkA=0, shrinkB=0))
        if not label:
            return
        (x1, y1), (x2, y2) = a.get_position(), b.get_position()
        mx, my = (x1 + x2) / 2, (y1 + y2) / 2
        if abs(x2 - x1) > abs(y2 - y1):  # horizontal edge: label above or below
            ax.text(mx, my + 0.55 * side, label, ha="center", va="bottom" if side > 0 else "top",
                    fontsize=18, style="italic", color=MUTED)
        else:  # vertical edge: label to one side
            ax.text(mx + 0.3 * side, my + nudge, label, ha="left" if side > 0 else "right", va="center",
                    fontsize=18, style="italic", color=MUTED)

    top.set_title("Structured knowledge", loc="left", fontsize=25, fontweight="bold", color=INK)
    chicago = node(top, (2.0, 5.6), "Chicago")
    illinois = node(top, (7.4, 5.6), "Illinois")
    us = node(top, (7.4, 1.4), "United States")
    blue = node(top, (2.0, 1.4), "Blue Line")
    arrow(top, chicago, illinois, "located in", side=1)
    arrow(top, illinois, us, "state of", side=-1, nudge=-0.6)
    arrow(top, blue, chicago, "runs through", side=1, nudge=0.6)

    bottom.set_title("Next-word statistics", loc="left", fontsize=25, fontweight="bold", color=INK)
    w_chicago = node(bottom, (1.8, 5.6), "Chicago")
    w_is = node(bottom, (5.6, 5.6), "is")
    w_cold = node(bottom, (1.4, 1.4), "cold")
    w_in = node(bottom, (5.6, 1.4), "in")
    w_windy = node(bottom, (8.6, 1.4), "windy")
    arrow(bottom, w_chicago, w_is)
    for w in (w_cold, w_in, w_windy):
        arrow(bottom, w_is, w)
    # Keep the golden-ratio box exactly: no tight bbox crop.
    fig.savefig(OUT / "two-approaches-to-ai.svg", transparent=True)
    plt.close(fig)


rnd_cost()
two_approaches()
